// createLibrary: parse createLibraryRequest → store.CreateLibrary → write
// libraryDTO. One domain call. Description is optional and defaults to "".
//
// @Summary      Create a scan library
// @Tags         libraries
// @ID           create-library
// @Router       /libraries [post]
// @Param        request body createLibraryRequest true "library to create"
// @Success      201 {object} libraryDTO
// @Failure      400 {object} errorBody
// @Failure      500 {object} errorBody
func (a *app) createLibrary(w http.ResponseWriter, r *http.Request) {
	var req createLibraryRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "malformed JSON body", false)
		return
	}
	id, err := a.deps.Store.CreateLibrary(r.Context(), req.ModuleID, req.RootPath, req.DisplayName, req.Description)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	writeJSON(w, http.StatusCreated, libraryDTO{
		ID:             id,
		ModuleID:       req.ModuleID,
		RootPath:       req.RootPath,
		DisplayName:    req.DisplayName,
		Description:    req.Description,
		StreamsEnabled: true, // the column default (D-8): a new library packages
	})
}

// patchLibrary: updateLibraryRequest → store.UpdateLibrary (+ SetLibraryChain
// when parsers present) → libraryDTO. Identity fields 400 pre-write (D2); an
// empty parser list is 400 (a chain is replaced, never cleared); missing id → 404.
//
// @Summary      Update a library's display name, description, and/or parser chain
// @Tags         libraries
// @ID           update-library
// @Router       /libraries/{id} [patch]
// @Param        id      path int                  true "library id"
// @Param        request body updateLibraryRequest true "fields to update"
// @Success      200 {object} libraryDTO
// @Failure      400 {object} errorBody
// @Failure      404 {object} errorBody
// @Failure      500 {object} errorBody
func (a *app) patchLibrary(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseInt(chi.URLParam(r, "id"), 10, 64)
	if err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "library id must be an integer", false)
		return
	}
	var req updateLibraryRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "malformed JSON body", false)
		return
	}
	if req.RootPath != nil || req.ModuleID != nil {
		writeError(w, http.StatusBadRequest, "bad_request",
			"root_path and module_id are immutable (moving a root re-identifies all items)", false)
		return
	}
	// Chain validation (element-pages 3.1): pure checks BEFORE either store
	// call — a rejected body leaves row and chain untouched; empty is 400
	// (a library chain is never cleared here).
	if req.Parsers != nil {
		if len(*req.Parsers) == 0 {
			writeError(w, http.StatusBadRequest, "bad_request",
				"parsers must be a non-empty ordered plugin id list (omit the field to keep the current chain)", false)
			return
		}
		if code, msg := a.validateParsers(r, *req.Parsers); code != 0 {
			writeError(w, code, "bad_request", msg, false)
			return
		}
	}
	// Naming-option validation (display-naming 3.2): pure checks BEFORE the
	// store call; a non-nil "" is the module-default reset.
	if req.NamingGroupStyle != nil {
		switch *req.NamingGroupStyle {
		case "", "clean", "raw":
		default:
			writeError(w, http.StatusBadRequest, "bad_request",
				`naming_group_style must be "", "clean", or "raw"`, false)
			return
		}
	}
	if req.NamingElementName != nil && !naming.ValidElementTemplate(*req.NamingElementName) {
		writeError(w, http.StatusBadRequest, "bad_request",
			"naming_element_name's {...} groups must each be exactly {title}, {season}, or {episode}", false)
		return
	}
	lib, err := a.deps.Store.UpdateLibrary(r.Context(), id, req.DisplayName, req.Description, req.StreamsEnabled, req.NamingGroupStyle, req.NamingElementName)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusNotFound, "not_found", "library "+chi.URLParam(r, "id")+" not found", false)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	if req.Parsers != nil {
		if err := a.deps.Store.SetLibraryChain(r.Context(), id, *req.Parsers); err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				writeError(w, http.StatusNotFound, "not_found", "library "+chi.URLParam(r, "id")+" not found", false)
				return
			}
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
			return
		}
	}
	writeJSON(w, http.StatusOK, toLibraryDTO(lib))
}

// getLibrary: {id} → store.GetLibrary → libraryDTO plus the additive module
// presentation block (element-pages 3.4), stored chain overlaid as footer
// order; nil closure serves the row without it; missing row → 404, errors → 500.
//
// @Summary      Get a single library with its module presentation block
// @Tags         libraries
// @ID           get-library
// @Router       /libraries/{id} [get]
// @Param        id path int true "library id"
// @Success      200 {object} libraryDTO
// @Failure      400 {object} errorBody
// @Failure      404 {object} errorBody
// @Failure      500 {object} errorBody
func (a *app) getLibrary(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseInt(chi.URLParam(r, "id"), 10, 64)
	if err != nil {
		writeError(w, http.StatusBadRequest, "bad_request", "library id must be an integer", false)
		return
	}
	// The handler's authority scope (6.2): resolved once here, passed to every
	// viewer-scoped read below; the Deps closure takes the stashed context.
	v, ctx := a.viewerFor(r)
	lib, err := a.deps.Store.GetLibrary(ctx, id, v)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			writeError(w, http.StatusNotFound, "not_found", "library "+chi.URLParam(r, "id")+" not found", false)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
		return
	}
	dto := toLibraryDTO(lib)
	if a.deps.ModulePresentation != nil {
		mp, err := a.deps.ModulePresentation(ctx, lib.ModuleID, id)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
			return
		}
		// Chain overlay (element-pages 3.1): the stored chain is the footer
		// group order overlaid onto the closure's config order; absent/empty
		// chain = config order.
		chain, err := a.deps.Store.GetLibraryChain(ctx, id)
		if err != nil {
			writeError(w, http.StatusInternalServerError, "internal_error", err.Error(), true)
			return
		}
		mp.Parsers = orderParserBindings(mp.Parsers, chain)
		dto.Module = &mp
	}
	writeJSON(w, http.StatusOK, dto)
}

// orderParserBindings overlays the stored parser chain onto the config order
// (element-pages 3.1): chain-named bindings first in chain order, the rest in
// config order after; empty chain is a no-op; no input mutation.
func orderParserBindings(bindings []ParserBinding, chain []string) []ParserBinding {
	if len(bindings) == 0 || len(chain) == 0 {
		return bindings
	}
	pos := make(map[string]int, len(chain))
	for i, id := range chain {
		if _, dup := pos[id]; !dup {
			pos[id] = i
		}
	}
	chained := make([]ParserBinding, 0, len(bindings))
	rest := make([]ParserBinding, 0, len(bindings))
	for _, b := range bindings {
		if _, ok := pos[b.ID]; ok {
			chained = append(chained, b)
		} else {
			rest = append(rest, b)
		}
	}
	sort.SliceStable(chained, func(i, j int) bool { return pos[chained[i].ID] < pos[chained[j].ID] })
	return append(chained, rest...)
}

